-- Tags: attack.credential-access, attack.t1555.003, attack.discovery, attack.t1217
-- Description: Detects file access to browser credential storage paths by non-browser processes, which may indicate credential access attempts.
-- Adversaries may attempt to access browser credential storage to extract sensitive information such as usernames and passwords or cookies.
-- This behavior is often commonly observed in credential stealing malware.
-- Converted by: Sigma Universal SIEM/EDR CLI

SELECT * FROM file WHERE ((((FileName LIKE '%\\Sputnik\\Sputnik%' OR FileName LIKE '%\\MapleStudio\\ChromePlus%' OR FileName LIKE '%\\QIP Surf%' OR FileName LIKE '%\\BlackHawk%' OR FileName LIKE '%\\7Star\\7Star%' OR FileName LIKE '%\\CatalinaGroup\\Citrio%' OR FileName LIKE '%\\Google\\Chrome%' OR FileName LIKE '%\\Coowon\\Coowon%' OR FileName LIKE '%\\CocCoc\\Browser%' OR FileName LIKE '%\\uCozMedia\\Uran%' OR FileName LIKE '%\\Tencent\\QQBrowser%' OR FileName LIKE '%\\Orbitum%' OR FileName LIKE '%\\Slimjet%' OR FileName LIKE '%\\Iridium%' OR FileName LIKE '%\\Vivaldi%' OR FileName LIKE '%\\Chromium%' OR FileName LIKE '%\\GhostBrowser%' OR FileName LIKE '%\\CentBrowser%' OR FileName LIKE '%\\Xvast%' OR FileName LIKE '%\\Chedot%' OR FileName LIKE '%\\SuperBird%' OR FileName LIKE '%\\360Browser\\Browser%' OR FileName LIKE '%\\360Chrome\\Chrome%' OR FileName LIKE '%\\Comodo\\Dragon%' OR FileName LIKE '%\\BraveSoftware\\Brave-Browser%' OR FileName LIKE '%\\Torch%' OR FileName LIKE '%\\UCBrowser\\%' OR FileName LIKE '%\\Blisk%' OR FileName LIKE '%\\Epic Privacy Browser%' OR FileName LIKE '%\\Nichrome%' OR FileName LIKE '%\\Amigo%' OR FileName LIKE '%\\Kometa%' OR FileName LIKE '%\\Xpom%' OR FileName LIKE '%\\Microsoft\\Edge%' OR FileName LIKE '%\\Liebao7Default\\EncryptedStorage%' OR FileName LIKE '%\\AVAST Software\\Browser%' OR FileName LIKE '%\\Kinza%' OR FileName LIKE '%\\Mozilla\\SeaMonkey\\%' OR FileName LIKE '%\\Comodo\\IceDragon\\%' OR FileName LIKE '%\\8pecxstudios\\Cyberfox\\%' OR FileName LIKE '%\\FlashPeak\\SlimBrowser\\%' OR FileName LIKE '%\\Moonchild Productions\\Pale Moon\\%')) AND ((FileName LIKE '%\\Profiles\\%' OR FileName LIKE '%\\User Data%')) AND (((FileName LIKE '%\\Login Data%' OR FileName LIKE '%\\Cookies%' OR FileName LIKE '%\\EncryptedStorage%' OR FileName LIKE '%\\WebCache\\%')) OR ((FileName="*cert9.db" OR FileName="*cookies.sqlite" OR FileName="*formhistory.sqlite" OR FileName="*key3.db" OR FileName="*key4.db" OR FileName="*Login Data.sqlite" OR FileName="*logins.json" OR FileName="*places.sqlite")))) AND NOT ((((Image="C:\\Program Files\\*" OR Image="C:\\Program Files (x86)\\*" OR Image="C:\\Windows\\System32\\*" OR Image="C:\\Windows\\SysWOW64\\*")) OR ((Image="*\\Sputnik.exe" OR Image="*\\ChromePlus.exe" OR Image="*\\QIP Surf.exe" OR Image="*\\BlackHawk.exe" OR Image="*\\7Star.exe" OR Image="*\\Sleipnir5.exe" OR Image="*\\Citrio.exe" OR Image="*\\Chrome SxS.exe" OR Image="*\\Chrome.exe" OR Image="*\\Coowon.exe" OR Image="*\\CocCocBrowser.exe" OR Image="*\\Uran.exe" OR Image="*\\QQBrowser.exe" OR Image="*\\Orbitum.exe" OR Image="*\\Slimjet.exe" OR Image="*\\Iridium.exe" OR Image="*\\Vivaldi.exe" OR Image="*\\Chromium.exe" OR Image="*\\GhostBrowser.exe" OR Image="*\\CentBrowser.exe" OR Image="*\\Xvast.exe" OR Image="*\\Chedot.exe" OR Image="*\\SuperBird.exe" OR Image="*\\360Browser.exe" OR Image="*\\360Chrome.exe" OR Image="*\\dragon.exe" OR Image="*\\brave.exe" OR Image="*\\torch.exe" OR Image="*\\UCBrowser.exe" OR Image="*\\BliskBrowser.exe" OR Image="*\\Epic Privacy Browser.exe" OR Image="*\\nichrome.exe" OR Image="*\\AmigoBrowser.exe" OR Image="*\\KometaBrowser.exe" OR Image="*\\XpomBrowser.exe" OR Image="*\\msedge.exe" OR Image="*\\LiebaoBrowser.exe" OR Image="*\\AvastBrowser.exe" OR Image="*\\Kinza.exe" OR Image="*\\seamonkey.exe" OR Image="*\\icedragon.exe" OR Image="*\\cyberfox.exe" OR Image="*\\SlimBrowser.exe" OR Image="*\\palemoon.exe")) OR ((Image LIKE '%\\Sputnik\\%' OR Image LIKE '%\\MapleStudio\\%' OR Image LIKE '%\\QIP Surf\\%' OR Image LIKE '%\\BlackHawk\\%' OR Image LIKE '%\\7Star\\%' OR Image LIKE '%\\Fenrir Inc\\%' OR Image LIKE '%\\CatalinaGroup\\%' OR Image LIKE '%\\Google\\%' OR Image LIKE '%\\Coowon\\%' OR Image LIKE '%\\CocCoc\\%' OR Image LIKE '%\\uCozMedia\\%' OR Image LIKE '%\\Tencent\\%' OR Image LIKE '%\\Orbitum\\%' OR Image LIKE '%\\Slimjet\\%' OR Image LIKE '%\\Iridium\\%' OR Image LIKE '%\\Vivaldi\\%' OR Image LIKE '%\\Chromium\\%' OR Image LIKE '%\\GhostBrowser\\%' OR Image LIKE '%\\CentBrowser\\%' OR Image LIKE '%\\Xvast\\%' OR Image LIKE '%\\Chedot\\%' OR Image LIKE '%\\SuperBird\\%' OR Image LIKE '%\\360Browser\\%' OR Image LIKE '%\\360Chrome\\%' OR Image LIKE '%\\Comodo\\%' OR Image LIKE '%\\BraveSoftware\\%' OR Image LIKE '%\\Torch\\%' OR Image LIKE '%\\UCBrowser\\%' OR Image LIKE '%\\Blisk\\%' OR Image LIKE '%\\Epic Privacy Browser\\%' OR Image LIKE '%\\Nichrome\\%' OR Image LIKE '%\\Amigo\\%' OR Image LIKE '%\\Kometa\\%' OR Image LIKE '%\\Xpom\\%' OR Image LIKE '%\\Microsoft\\%' OR Image LIKE '%\\Liebao7\\%' OR Image LIKE '%\\AVAST Software\\%' OR Image LIKE '%\\Kinza\\%' OR Image LIKE '%\\Mozilla\\%' OR Image LIKE '%\\8pecxstudios\\%' OR Image LIKE '%\\FlashPeak\\%' OR Image LIKE '%\\Moonchild Productions\\%')) OR (Image = 'System' AND ParentImage = 'Idle'))) AND NOT (((Image LIKE '%\\Microsoft\\Windows Defender\\%' AND (Image="*\\MpCopyAccelerator.exe" OR Image="*\\MsMpEng.exe")) OR (ParentImage = 'C:\\Windows\\System32\\msiexec.exe') OR (Image="*\\everything.exe") OR ((Image="*\\thor.exe" OR Image="*\\thor64.exe")))))
